function terrainHeight(x,z){
  const n=Math.sin(x*.021+1.4)*Math.cos(z*.018)*3.2 + Math.sin(x*.054+z*.037)*1.0 + Math.cos(z*.009-x*.012)*2.1;
  const hills=Math.max(0,Math.sin((x+z*.65)*.008+1.4))**2*9;
  const ridges=Math.max(0,Math.sin((x*.55-z)*.011))**3*16;
  return n+hills+ ridges*(Math.min(1,Math.max(0,(Math.abs(x)+Math.abs(z)-220)/230)));
}
function rndFactory(seed=123){let s=seed|0;return()=>{s=(s*1664525+1013904223)|0;return(s>>>0)/4294967296}}
