  random=rndFactory(regionIndex*195+72);
  const size=1400,segments=190,geo=new THREE.PlaneGeometry(size,size,segments,segments);geo.rotateX(-Math.PI/2);
  const p=geo.attributes.position, colors=[];
  const palette=new THREE.Color(region.color);
  const moss=new THREE.Color('#7f8860'),dark=new THREE.Color('#4c624b'),stone=new THREE.Color('#8a806c');
  for(let i=0;i<p.count;i++){
    const x=p.getX(i),z=p.getZ(i),h=terrainHeight(x,z);p.setY(i,h);
    const variation=(Math.sin(x*.033)*Math.cos(z*.041)+Math.sin(z*.09+x*.03))*.055;
    const slope= Math.abs(h-terrainHeight(x+2,z))*.04;
    let c=palette.clone().lerp(moss,THREE.MathUtils.clamp(.29+variation+slope,0,.68));
    if(h>12)c.lerp(stone,Math.min(.7,(h-12)/32)); else if(h< -4)c.lerp(dark,.23);
    colors.push(c.r,c.g,c.b);
  }
  geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();
  groundMesh=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:.96}));groundMesh.receiveShadow=true;scene.add(groundMesh);
  // Far ridgelines: layered silhouettes fade softly into atmospheric distance.
  const ridgeMats=[mat('#576d63'),mat('#708078'),mat('#87928a')];
  for(let ring=0;ring<3;ring++){
    const count=34,rad=430+ring*93;
    for(let i=0;i<count;i++){
      const a=i/count*Math.PI*2, r=rad+random()*55, h=60+random()*95;
      const g=new THREE.ConeGeometry(42+random()*46,h,5);const mountain=mesh(g,ridgeMats[ring],Math.cos(a)*r,h/2-7,Math.sin(a)*r);mountain.rotation.y=random()*2;
      mountain.castShadow=false;mountain.receiveShadow=false;
    }
  }
  const trunk=mat('#514839'),leafMats=[mat('#405e42'),mat('#526d45'),mat('#6a7950'),mat('#77805a')];
  // Thousands of low-poly forest crowns, clustered in irregular clearings.
  for(let i=0;i<145;i++){
    const a=random()*Math.PI*2,r=34+random()*410,x=Math.cos(a)*r,z=Math.sin(a)*r;
    if(Math.hypot(x-player.pos.x,z-player.pos.z)<21||Math.hypot(x-objective.x,z-objective.z)<14)continue;
    const y=terrainHeight(x,z),scale=.75+random()*1.25;
    const stem=mesh(new THREE.CylinderGeometry(.28*scale,.55*scale,5.3*scale,5),trunk,x,y+2.6*scale,z);stem.castShadow=true;
    const crown=mesh(new THREE.IcosahedronGeometry(3.4*scale,1),leafMats[Math.floor(random()*leafMats.length)],x,y+6.6*scale,z);crown.castShadow=true;crown.receiveShadow=true;
    if(random()>.65){const c2=mesh(new THREE.IcosahedronGeometry(2.5*scale,1),leafMats[Math.floor(random()*leafMats.length)],x+2.1*scale,y+6.4*scale,z-.5*scale);c2.castShadow=true;}
  }
  // Layered grass, tiny flowers and weathered rocks to bring the foreground to life.
  const rockMat=mat('#77766a'), grassMat=mat(regionIndex===4||regionIndex===5?'#b4a176':'#83926a');
  for(let i=0;i<180;i++){
    const a=random()*Math.PI*2,r=5+random()*85,x=Math.cos(a)*r,z=Math.sin(a)*r;
    const h=terrainHeight(x,z);
    if(random()>.6){const rock=mesh(new THREE.DodecahedronGeometry(.6+random()*1.5,0),rockMat,x,h+.5,z);rock.scale.y=.5+random();rock.rotation.set(random(),random(),random());rock.castShadow=true;}
    else{const tuft=mesh(new THREE.ConeGeometry(.22+random()*.2,.7+random()*.8,3),grassMat,x,h+.35,z);tuft.rotation.z=(random()-.5)*.4;}
  }
}
