  c.strokeStyle='rgba(188,211,183,.10)';c.lineWidth=1*dpr;
  for(let lon=-150;lon<=150;lon+=30){const [x]=mapPoint(lon,0,w,h);c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke()}
