}
async function loadCountries(){try{const response=await fetch('/countries.geo.json');if(!response.ok)throw new Error('Country boundary data unavailable');const data=await response.json();countryFeatures=data.features||[];drawWorldMap();buildZoneList()}catch(error){console.warn('World map boundaries could not be loaded',error);toast('MAP DATA UNAVAILABLE · RETRY LATER')}}

